SELECT t.id AS task_id, t.instance_id AS instance_id, i.biz_type AS biz_type, i.biz_id AS biz_id, t.node_key AS node_key, t.node_name AS node_name, t.assignee_id AS assignee_id, t.delegated_from AS delegated_from, t.status AS status, t.due_at AS due_at, t.round_no AS round_no, t.version AS version FROM wf_task t JOIN wf_instance i ON i.id = t.instance_id WHERE t.assignee_id = #{assigneeId} AND t.status = #{status}
AND i.biz_type = #{bizType}
ORDER BY t.due_at ASC NULLS LAST, t.created_at ASC LIMIT #{limit} OFFSET #{offset}

SELECT count(*)
  FROM wf_task t
  JOIN wf_instance i ON i.id = t.instance_id
 WHERE t.assignee_id = #{assigneeId}
   AND t.status = #{status}

   AND i.biz_type = #{bizType}
